using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Collections.Generic;using System.Windows.Forms;using DeadlockOverlay;
class FinalizationTests {
 static int count;static void C(bool ok,string label){if(!ok)throw new Exception(label);count++;}
 [STAThread]static void Main(){Application.EnableVisualStyles();UiReview.Active=true;string path=Path.Combine(Path.GetTempPath(),"deadlock-party-test-"+Guid.NewGuid()+".json");var registry=new PartyMarkers(path);var groups=new Dictionary<long,PartyInfo>();for(int i=0;i<6;i++){var info=new PartyInfo{Confidence=PartyConfidence.Likely,Members=new long[]{i*2+1,i*2+2}};groups[i*2+1]=info;groups[i*2+2]=info;}registry.Assign("test",groups);C(groups.Values.Select(p=>p.Color).Distinct().Count()==6,"six unique colors");C(groups.Values.Select(p=>p.Group).Distinct().OrderBy(x=>x).SequenceEqual(new[]{"A","B","C","D","E","F"}),"readable labels");var before=groups[1].Group;new PartyMarkers(path).Assign("test",groups);C(groups[1].Group==before,"restart stable");groups.Remove(3);groups.Remove(4);registry.Assign("test",groups);C(groups[1].Group==before,"removing another group keeps label");File.Delete(path);
 var players=Enumerable.Range(0,12).Select(i=>new Player{Slot=i,Team=i<6?2:3,Hero=15,Name=i==0?new string('W',110):"Demo player "+i,HeroName="Bebop",Damage=1000+i*500,ObjectDamage=i*10,Healing=i*30,Souls=20000+i*100,Kills=4,Deaths=2,Assists=6}).ToArray();var summary=new MatchSummary{MatchId="123",Players=players,DurationSeconds=1800,WinningTeam=2};C(ReviewAnalysis.Compare(summary,players[11]).Contains("leader"),"leaders use actual match totals");C(ReviewAnalysis.Previous(players[0],summary).Contains("No suitable"),"no fabricated prior comparison");
 var detail=new ScoutMatchDetail{Available=true,Hero=15,Seconds=1800,LastSecond=1800,Timeline=Enumerable.Range(0,10).Select(i=>new ReviewSample{Second=i*200,Damage=i*100,Souls=1000+i*500,Objectives=i*10,Healing=0}).ToArray(),Purchases=new[]{new ReviewPurchase{Item=123,Second=0,Sold=100}}};var flags=BindingFlags.Instance|BindingFlags.NonPublic;
 using(var svc=new ScoutDetailService(Path.GetTempPath()))using(var view=new PlayerDetailCanvas(summary,players[0])){((Dictionary<string,ScoutMatchDetail>)typeof(ScoutDetailService).GetField("matches",flags).GetValue(svc))["1-123"]=detail;typeof(PlayerDetailCanvas).GetField("recorded",flags).SetValue(view,svc);typeof(PlayerDetailCanvas).GetField("recordedAccount",flags).SetValue(view,1L);typeof(PlayerDetailCanvas).GetField("recordedMatch",flags).SetValue(view,123L);view.CreateControl();foreach(var size in new[]{new Size(1920,1080),new Size(2560,1440)})foreach(int dpi in new[]{96,120,144,192})foreach(int tab in new[]{0,1,2,3}){view.Size=size;view.SetReviewDpi(dpi);typeof(PlayerDetailCanvas).GetField("selected",flags).SetValue(view,tab);using(var bmp=new Bitmap(size.Width,size.Height))view.DrawToBitmap(bmp,new Rectangle(Point.Empty,size));C(view.Height==size.Height,"viewport remains fixed; scroll not giant bitmap");if(tab==1){var tips=(List<KeyValuePair<RectangleF,string>>)typeof(PlayerDetailCanvas).GetField("tips",flags).GetValue(view);C(tips.Count(t=>t.Value.Contains(" · "))==40,"exactly ten samples in each chart");}}}
 Console.WriteLine("Finalization checks passed: "+count);}
}
